function vignetteProcess(data,w,h,opts){
  opts=opts||{};
  var str=opts.strength!=null?opts.strength:0.6;
  var rad=opts.radius!=null?opts.radius:0.8;
  if(str<0)str=0; else if(str>1)str=1;
  if(rad<0.01)rad=0.01; else if(rad>1)rad=1;
  var cx=(opts.centerX!=null?opts.centerX:0.5)*w;
  var cy=(opts.centerY!=null?opts.centerY:0.5)*h;
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var dx=(x-cx)/w, dy=(y-cy)/h;
    var d=Math.sqrt(dx*dx+dy*dy);
    var nd=d/rad;
    var f=1-str*(nd>1?1:nd);
    if(f<0)f=0;
    var i=(y*w+x)*4;
    out[i]=data[i]*f; out[i+1]=data[i+1]*f; out[i+2]=data[i+2]*f; out[i+3]=data[i+3];
  }
  return out;
}

var EXPORTS={vignetteProcess:vignetteProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.VignetteForgePure = EXPORTS; }
